import { readFileSync } from "node:fs";
import { ByteStream, SeqStream } from "bytestreamjs";

/**
 * Fixture fonts generated by `test/fixtures/generate.py`.
 */
export type FixtureName = "FontJSTest-Regular.ttf" | "FontJSTest-DSIG.ttf";

export function readFixture(name: FixtureName | "signature.der"): Uint8Array {
  return new Uint8Array(readFileSync(new URL(name, import.meta.url)));
}

export function fixtureStream(name: FixtureName): SeqStream {
  const bytes = readFixture(name);

  return new SeqStream({ stream: new ByteStream({ buffer: bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) }) });
}
